int bfs(vector<string>& g) {
    int R = g.size(), C = g[0].size();
    vector<vector<int>> d(R, vector<int>(C, -1));
    queue<pair<int,int>> q; q.push({0, 0}); d[0][0] = 0;
    int dr[] = {1, -1, 0, 0}, dc[] = {0, 0, 1, -1};
    while (!q.empty()) {
        auto [r, c] = q.front(); q.pop();
        for (int k = 0; k < 4; k++) {
            int y = r + dr[k], x = c + dc[k];
            if (y < 0 || x < 0 || y >= R || x >= C) continue;
            if (g[y][x] == '#' || d[y][x] >= 0) continue;
            d[y][x] = d[r][c] + 1; q.push({y, x});
        }
    }
    return d[R - 1][C - 1];
}

int R, C;
void dfs(vector<string>& g, int r, int c) {
    if (r < 0 || c < 0 || r >= R || c >= C || g[r][c] != '1') return;
    g[r][c] = '0';                      // mark visited
    dfs(g, r + 1, c); dfs(g, r - 1, c);
    dfs(g, r, c + 1); dfs(g, r, c - 1);
}
int islands(vector<string>& g) {
    R = g.size(), C = g[0].size();
    int n = 0;
    for (int r = 0; r < R; r++)
        for (int c = 0; c < C; c++)
            if (g[r][c] == '1') n++, dfs(g, r, c);
    return n;
}
